import {
    Shield
} from 'lucide-react';

import { KycLogViewModal } from '@/Components/Feature/Backend/User/KycLogViewModal';
import { KycLogUpdateForm } from '@/Components/Forms/Backend/User/KycLogUpdateForm';
import StatusBadge from '@/Components/UI/StatusBadge';
import { useTranslations } from '@/Hooks/useTranslations';
import type { CrudConfig, CrudPageProps } from '@/Types/crud';
import { limitText } from '@/Utils/helpers';
import z from 'zod';

export function useKycLogConfig(props: CrudPageProps): CrudConfig {

    const { t } = useTranslations();

    const modelProperty = props?.modelProperty;
    const routePrefix = modelProperty?.routePrefix;

    const baseBreadcrumbs = [
        { label: t('Dashboard'), href: route('backend.dashboard') },
        { label: t('KYC Logs'), href: route(`${routePrefix}.index`) },
    ];

    return {

        /* -------------------------------------------------
         * BASIC
         * -------------------------------------------------*/
        resource: 'kyc-log',
        resourcePlural: 'kyc-logs',
        title: t('KYC Logs'),
        description: t('Manage user KYC verification requests'),

        formComponent: KycLogUpdateForm,

        /* -------------------------------------------------
         * ROUTES
         * -------------------------------------------------*/
        routes: {
            index: `${routePrefix}.index`,
            update: `${routePrefix}.update`,
            show: `${routePrefix}.show`,
        },


        viewDisplayMode: 'modal',
        viewDialogConfig: {
            size: 'xl',
            showStats: true,
            showErrors: true,
            showDownloadButton: true,
            title: t('View'),
            description: t('Kyc log details'),
            viewComponent: KycLogViewModal,
        },



        formDisplayMode: 'modal',

        statusType: 'binary',

        breadcrumbs: {
            index: [
                { label: t('Dashboard'), href: route('backend.dashboard') },
                { label: t('Users'), href: null, active: true },
            ],
            create: [
                ...baseBreadcrumbs,
                { label: t('Create'), href: null, active: true },
            ],
            update: [
                ...baseBreadcrumbs,
                { label: t('Update'), href: null, active: true },
            ],
        },

        /* -------------------------------------------------
         * TABLE
         * -------------------------------------------------*/
        table: {
            selectable: false,
            searchable: true,
            sortable: true,
            serializable: true,

            searchPlaceholder: t('Search by user name, email...'),

            defaultSort: 'created_at',
            defaultSortDirection: 'desc',

            emptyMessage: t('No KYC logs found'),
            emptyMessageIcon: Shield,

            columns: [

                {
                    key: 'user',
                    label: t('User'),
                    sortable: false,
                    render: (row: any) => (
                        <div className="flex flex-col">
                            <span className="font-medium">{row.user?.name}</span>
                            <span className="text-xs text-gray-500">{row.user?.email}</span>
                        </div>
                    )
                },

                {
                    key: 'status',
                    label: t('Status'),
                    sortable: false,
                    render: (row: any) => <StatusBadge status={row.status} />
                },

                {
                    key: 'note',
                    label: t('Admin Note'),
                    sortable: false,
                    render: (row: any) => (
                        <span className="text-sm text-gray-600">
                            {row.note ? limitText(row.note, 30) : '-'}
                        </span>
                    )
                },



                /* CREATED */
                {
                    key: 'created_at',
                    label: t('Created At'),
                    sortable: false,
                    renderType: 'date'
                },

            ],
        },

        /* -------------------------------------------------
         * FORM (UPDATE ONLY)
         * -------------------------------------------------*/
        form: {
            title: {
                edit: t('Update KYC Status'),
                create: t('Update KYC Status'),
            },
            submitButtonText: {
                edit: t('Update'),
                create: t('Update'),
            },

            fields: [
                {
                    name: 'value',
                    label: t('Status'),
                    type: 'select',
                    required: true,
                    options: [
                        { value: 'pending', label: t('Pending') },
                        { value: 'approved', label: t('Approved') },
                        { value: 'rejected', label: t('Rejected') },
                    ],
                },
                {
                    name: 'note',
                    label: t('Admin Note'),
                    type: 'textarea',
                    required: false,
                    placeholder: t('Write internal note...'),
                }
            ],
        },


        // formValidationRules
        formValidationRules: {
            value: z.string().min(1, 'Status is required'),
            note: z.any().optional(),
        },




        /* -------------------------------------------------
         * FILTERS
         * -------------------------------------------------*/
        filters: {
            searchFields: ['name', 'email', 'username', 'phone'],
            filterFields: [
                {
                    key: 'status',
                    label: t('Status'),
                    type: 'select',
                    options: [
                        { value: '', label: t('All') },
                        { value: 'pending', label: t('Pending') },
                        { value: 'approved', label: t('Approved') },
                        { value: 'rejected', label: t('Rejected') },
                    ]
                },
                {
                    key: 'date_range',
                    label: t('Date Range'),
                    type: 'daterange',
                }
            ],
        },

        /* -------------------------------------------------
         * PERMISSIONS
         * -------------------------------------------------*/
        permissions: {
            actions: {
                view: 'kyc-log.view',
                edit: 'kyc-log.edit',
                show: 'kyc-log.view',
            }
        },



        /* -------------------------------------------------
         * VIEW CONFIG
         * -------------------------------------------------*/
        view: {
            title: t('KYC Details'),
            icon: Shield,

            sections: [
                {
                    title: t('User Info'),
                    fields: ['user']
                },
                {
                    title: t('KYC Data'),
                    fields: ['data']
                },
                {
                    title: t('Files'),
                    fields: ['files']
                },
                {
                    title: t('Meta'),
                    fields: ['created_at', 'status', 'note']
                }
            ]
        },

        /* -------------------------------------------------
         * LABELS
         * -------------------------------------------------*/
        labels: {
            singular: 'KYC Log',
            plural: 'KYC Logs',
            key: 'kyc_log',
        },

        /* -------------------------------------------------
         * ALERT
         * -------------------------------------------------*/
        saveAlertInfo: {
            title: t('KYC Management'),
            description: t('Approve or reject user identity verification requests.')
        }
    };
}